## IIFE
### js
```js
(() => {
  print(1)
})();

(function() {
  print(2)
})();

(() => {
  print(1)
})()
(function() {
  print(2)
})();
```
### lua
```lua
(function()
  print(1)
end)();
(function()
  print(2)
end)();
(function()
  print(1)
end)()(function()
  print(2)
end)()
```
## assignment
### js
```js
let u, v;
[u, v] = [1, 2]
const foo = 1
const object = { o1: 'o1', o2: 'o2' }, array = [1, 2]
// eslint-disable-next-line no-undef
const h1 = h2 = h3 = 'title'
const { a, b: bAlias, ...rest } = { a: 1, b: 2, c: 3, d: 4 }
const [x, y, ...others] = [1, 2, 3, 4]
const e = 1, f = 'a', { o1, o2: o22 } = object, [a1, a2] = array
```
### lua
```lua
local u;
local v;
u, v = unpack(array{
  1,
  2
});
local foo = 1;
local object = {
  o1 = 'o1',
  o2 = 'o2'
};
local array = array{
  1,
  2
};
local h3 = 'title';
local h2 = h3;
local h1 = h2;
local a, bAlias, rest;
do
  local __tmp = {
    a = 1,
    b = 2,
    c = 3,
    d = 4
  };
  a = __tmp.a;
  bAlias = __tmp.b;
  rest = {};
  for k, v in pairs(__tmp) do
    if k ~= "a" and k ~= "b" then
      rest[k] = v
    end
  end
end;
local x, y, others;
do
  local __tmp = array{
    1,
    2,
    3,
    4
  };
  x = __tmp[1];
  y = __tmp[2];
  others = {};
  for __i = 3, # __tmp do
    others[# others + 1] = __tmp[__i]
  end
end;
local e = 1;
local f = 'a';
local o1, o22;
do
  local __tmp = object;
  o1 = __tmp.o1;
  o22 = __tmp.o2
end;
local a1, a2;
do
  local __tmp = array;
  a1 = __tmp[1];
  a2 = __tmp[2]
end
```
## class
### js
```js
class BasePosition {
  say(word = 'base haha') {
    console.log(`Base say: ${word}`)
  }
}
class Position extends BasePosition {
  static insCount = 0
  start = 0
  end = 1;
  constructor(name, x = 1, y = 2, ...numbers) {
    super()
    Position.insCount++
    this.name = name
    this.x = x
    this.y = y
    this.numbers = numbers
  }
  static echoInsCount() {
    console.log(this.insCount)
  }
  echoPosition() {
    console.log(this.name, this.x, this.y)
  }
  echoNumbersLength() {
    console.log('numbers length:', this.name, this.numbers.length)
  }
  say(word = 'haha') {
    super.say(word)
    console.log(`${this.name} say: ${word}, first number is ${this.numbers[0]}`)
  }
}

const p1 = new Position('p1', 1, 2, 3, 4)
Position.echoInsCount()
const p2 = new Position('p2', 10, 20, 30, 40)
Position.echoInsCount()
p1.echoPosition()
p2.echoPosition()
p1.say('hello')
p1.say.call(p2)
p1.echoNumbersLength('a', 'b', 'c')
p1.echoNumbersLength.apply(p2, [1, 2])
```
### lua
```lua
local BasePosition = setmetatable({}, {
  __call = function(t)
    local self = t:new();
    self:constructor();
    return self;
  end
})
BasePosition.__index = BasePosition
function BasePosition.new(cls)
  return setmetatable({}, cls)
end
function BasePosition:constructor()
end
function BasePosition:say(word)
  if word == nil then
    word = 'base haha'
  end
  print(string.format([=[Base say: %s]=], word))
end;
local Position = setmetatable({}, {
  __index = BasePosition,
  __call = function(t, name, x, y, ...)
    local self = t:new();
    self:constructor(name, x, y, ...);
    return self;
  end
})
Position.__index = Position
Position.insCount = 0
function Position.new(cls)
  return setmetatable({
    start = 0,
    ["end"] = 1
  }, cls)
end
function Position:constructor(name, x, y, ...)
  if x == nil then
    x = 1
  end;
  if y == nil then
    y = 2
  end
  local numbers = {
    ...
  };
  BasePosition.constructor(self);
  Position.insCount = Position.insCount + 1;
  self.name = name;
  self.x = x;
  self.y = y;
  self.numbers = numbers
end
function Position:echoInsCount()
  print(self.insCount)
end;
function Position:echoPosition()
  print(self.name, self.x, self.y)
end;
function Position:echoNumbersLength()
  print('numbers length:', self.name, # self.numbers)
end;
function Position:say(word)
  if word == nil then
    word = 'haha'
