                type: ComponentType.ActionRow,
                components: button
              }],
              files
            });
          }
          context.waitUntil(followUpRequest()); // function to followup, wait for request and update response
          return deferReply(); //
        }

        // ... Other cases

        default:
          return error(400, "Unknown Command");
      }
    });
  }
});
// ...
